window.POETRY_REGISTER("v5-strict-12-12-0-5283151c761c.js",{"poems":[[49184,2],[49185,2],[52301,2],[54559,2],[57946,2],[92652,7],[109552,7],[136930,7],[141934,7],[178405,7],[180336,7],[180825,7],[180834,7],[180859,7],[180957,7],[181271,7],[185593,7],[186938,7],[187948,7],[191608,7],[209864,7],[229247,7],[233439,7],[236780,7],[264987,7],[264994,7],[265019,7],[271935,7],[271973,7],[272079,7],[272338,7],[272362,7],[275121,7],[281635,7],[285959,7],[288519,7],[289440,7],[301577,7],[301600,7],[336238,9],[336240,9],[344014,9],[347215,9],[360398,9],[363660,9],[488586,8],[589882,8],[636941,15],[650074,5],[653219,5],[739686,20]],"pairs":[["曾未若轩后顺风兮清静自化","曾未若臯陶迈种兮温恭允塞",0],["君不见四皓避秦峨峨恋商岭","君不见二疎辞汉飘飘归故林",1],["唐清九壁诗序石刻在琵琶泓","朝议大夫高平郡别驾权澈词",2],["如窦叔向诗误归已经继之类","岑仲勉李嘉言二先生已指出",3],["第五首题中裴草然上空一格","恐非表明裴草然而为诗作者",4],["甚或此诗集只是赵志抄录者","内中连他的作品一首也没有",4],["输卒引繂兮蓬首裸体剧缧囚","赤日上煎兮胶津蹙气塞咽喉",5],["潏汨沸渭兮澎湃奔波而霈来","崩腾覆溺兮夫岂河伯之不仁",6],["平生之梗槩兮欲萧萧而去眼","将绝之言语兮忽历历而经心",7],["仙人偓佺兮自言其居瑶之圃","一日一夕兮飞相往来不可数",8],["我所参得底只要涅槃堂里用","且不听杜撰禅师三千八百画",9],["三世同参或一段合宗家之事","大千等量破微尘出自己之经",10],["齐物飘飘兮流梦似随蝴蝶去","亡机荡荡兮清闲还与白鸥分",11],["老兔卧寒兮清炯炯明月之窟","长鲸𩥇海兮光漾漾珊瑚之林",12],["法不当情兮平等得定慧之学","心无所住兮自然见离微之时",13],["斲轮之工兮拟谁授克家之学","抱瓮之朴兮将自灌丈人之园",14],["胡饼馒头有变通而绍祖供职","莲华荷叶没科臼而说禅判宦",15],["说法则雷轰电激乎仰山之上","入灭则霜清月落乎连水之湄",16],["正偏融融而路断于鸟道之表","君臣堂堂而容俨于玉殿之中",17],["山多乔木兮不能为吾之栋梁","水多深阻兮不能为吾之舟航",18],["二百年前江西湖南杀人放火","三千里外山东河北夺鼓搀旗",19],["既不能挺长剑以抉九天之云","又不能持斗魁以回万物之春",20],["世传秀句我既不能如唐王维","民依慈母亦复不能如汉杜诗",21],["感北江之东注兮溯洄之宛宛","羌顺天而不极兮荡波之有沔",22],["扪萝以寻于烂平兮既不可见","莽白云之廿里兮欲进兮焉求",23],["岂不闻东宫婕妤作歌悲团扇","又不闻长门阿娇买赋捐黄金",24],["君不见燕颔虎颈班超侯万里","又不见风声鹤唳谢玄破肥水",25],["君不见少君诧安期海上之枣","又不见坡仙咏安期宅边之蒲",26],["胡大僇之正不致于林甫之流","而所遭之惨乃及于泉明之辈",27],["论其钩格则得纡余曲致之体","考其纵逸则妙雍容不迫之状",28],["予意其因以寓墨池模倣之妙","而未必徒以诧记事备言之述",29],["我歌慷慨兮岂独私为岷峨愁","劳心悄悄兮实与天地先其忧",30],["我不愿筑受降城朔方职总管","又不愿金狨系马西池万人看",31],["君不见前年三百青铜米一斗","又不见去年蕨根掘尽不充口",32],["胡不学鲛人细织冰绡制云裾","胡不从湘君缓移桂櫂搴芙蕖",33],["船架半壑兮使星会泛河汉归","机留古洞兮天孙去作牵牛妻",34],["捏定五十三人性命若一藕丝","擎起百一十城世界如一荷叶",35],["冬寒春暖兮湖草几番之青青","今来古往兮人物几代之废兴",36],["读范老堂记则怀憩堂于出守","问祈国里曲则想持帽于方童",37],["可以坐三大如来于中闲正面","可以奉五百罗汉于东西两阿",38],["才过了一百五日上坟的日月","早来到二十四夜祭灶的时节",39],["他那里鞍儿马儿身子儿劣怯","我这里眉儿眼儿脸脑儿乜斜",40],["南极老人称觞北斗挹酌天酒","愿与九州四海同上千万岁寿",41],["灶兮灶兮但使我生不富不贫","适饱适饥朝从尔餐夕从尔糜",42],["写以文考赋鲁城之笔千万字","吹以东坡吊孟德之箫声呜呜",43],["然大人虎变有不可得而测者","岂非寻常之中而有筑岩之傅",44],["君不闻宣尼耕稼不如一老农","又不闻子舆痛辟许公学神农",45],["来者如黄河之源滔滔而不竭","去者如长江之水滚滚而不回",46],["我不能同五百人一死从田横","会当直入四百峰师事安期生",47],["你看起初时茹毛饮血心已狠","燧人氏泼油添盐又加上熬煎",48],["那迂学包子看书只管瞎赞叹","只怕这其间的字眼有些讹传",48],["到于今有名头的妇人称十乱","就是孔圣人的书本也把他夸",48],["就是那风流常山是何等英豪","空使杀英雄没捞着块中原土",48],["次后来糊里糊涂又挨了几日","教一个扫槽的刘裕饼卷了葱",48],["在台城饿断了肝花想口蜜水","一辈子干念些弥陀瞎烧了香",48],["贪恋着巢剌王的妃子容颜好","难为他兄弟的炕头怎样去扒",48],["只有个殿下的猢狲掴他几掴","从此后朱温家爷们灭了人理",48],["或悬一发于碍风回日之高标","或藏一缕于停云隐雾之深松",49],["君不见醉吟居士不归海上山","又不见昌黎先生屈曲自世闲",50]]});
